@tool_spec(
    input_model=ModifyLabelsRequest,
    output_model=ModifyLabelsResponse,
    error_model=[
        ErrorObject(
            TypeError,
            [
                "Raised if 'fileId' is not a string.",
                "Raised if 'labelModifications' is not a list.",
            ],
        ),
        ErrorObject(
            ValidationError,
            [
                "Raised if 'fileId' is an empty string or consists only of whitespace.",
                "Raised if 'labelModifications' is empty.",
                "Raised if 'labelId' in a modification is empty.",
                "Raised if 'fieldId' in a field modification is empty.",
                "Raised if both 'removeLabel' and 'fieldModifications' are specified for the same label.",
                "Raised if setDateValues contains a value that is not in YYYY-MM-DD format.",
                "Raised if setIntegerValues contains a non-numeric value or a value outside the signed int64 range.",
                "Raised if setUserValues contains a value that is not a valid email address.",
            ],
        ),
        ErrorObject(
            ResourceNotFoundError,
            [
                "Raised if the default 'me' user is missing or not configured.",
                "Raised if the file with the specified 'fileId' does not exist.",
            ],
        ),
        ErrorObject(
            InvalidRequestError,
            [
                "Raised if the request contains conflicting parameters.",
                "Raised if multiple value setters are specified for the same field modification.",
            ],
        ),
        ErrorObject(
            PermissionDeniedError,
            [
                "Raised if the caller lacks writer access or higher on the file.",
            ],
        ),
    ],
    description="""Modifies the set of labels applied to a file.

    This method allows adding, updating, or removing labels and their fields on a file.
    All modifications are atomic - they all succeed or all fail together.
    Labels are stored directly on the file object in the 'labels' array.

    Supports all 5 field types: dateString, integer, selection, text, user.""",
    spec={
        "name": "modify_file_labels",
        "description": """Modifies the set of labels applied to a file.

        This method allows adding, updating, or removing labels and their fields on a file.
        All modifications are atomic - they all succeed or all fail together.
        Labels are stored directly on the file object in the 'labels' array.""",
        "parameters": {
            "type": "object",
            "properties": {
                "fileId": {
                    "type": "string",
                    "description": "The ID of the file to modify labels on.",
                    "nullable": False,
                },
                "labelModifications": {
                    "type": "array",
                    "description": "List of label modifications to apply.",
                    "nullable": False,
                    "items": LABEL_MODIFICATION_SCHEMA,
                },
            },
            "required": ["fileId", "labelModifications"],
        },
        "response": MODIFY_LABELS_RESPONSE_SCHEMA,
    },
)
def modifyLabels(fileId: str, labelModifications: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Modifies the set of labels applied to a file. This method allows adding, updating, or
    removing labels and their fields on a file. All modifications are atomic - they all
    succeed or all fail together. Labels are stored directly on the file object in the
    'labels' array.

    Args:
        fileId (str):
            The ID of the file to modify labels on. Required.
        labelModifications (List[Dict[str, Any]]):
            List of label modifications to apply. Required.
            Fields:
            - labelModifications[].labelId (str): The ID of the label to modify. Required.
            - labelModifications[].kind (str): Resource type identifier (always
              'drive#labelModification'). Optional; default: 'drive#labelModification'.
            - labelModifications[].fieldModifications (list[dict] | None): List of field
              modifications to apply to this label. Optional; nullable.
            - labelModifications[].fieldModifications[].fieldId (str): The ID of the field
              to modify. Required.
            - labelModifications[].fieldModifications[].kind (str): Resource type identifier
              (always 'drive#labelFieldModification'). Optional; default:
              'drive#labelFieldModification'.
            - labelModifications[].fieldModifications[].setDateValues (list[str] | None):
              RFC 3339 formatted dates to set for a dateString field. Optional; nullable.
            - labelModifications[].fieldModifications[].setIntegerValues (list[str] | None):
              Integer values as strings to set for an integer field. Optional; nullable.
            - labelModifications[].fieldModifications[].setSelectionValues (list[str] |
              None): Selection choice IDs to set for a selection field. Optional; nullable.
            - labelModifications[].fieldModifications[].setTextValues (list[str] | None):
              Text values to set for a text field. Optional; nullable.
            - labelModifications[].fieldModifications[].setUserValues (list[str] | None):
              User email addresses to set for a user field. Optional; nullable.
            - labelModifications[].fieldModifications[].unsetValues (bool | None): If True,
              removes all values from this field. Optional; nullable.
            - labelModifications[].removeLabel (bool | None): If True, removes this label
              entirely from the file. Optional; nullable.

    Returns:
        Dict[str, Any]:
            Response from files.modifyLabels endpoint.
            Fields:
            - kind (str): Resource type identifier (always 'drive#modifyLabelsResponse').
              Optional; default: 'drive#modifyLabelsResponse'.
            - modifiedLabels (list[dict] | None): List of labels that were added or updated.
              Optional; nullable.
            - modifiedLabels[].id (str): The ID of the label. Required.
            - modifiedLabels[].kind (str): Resource type identifier (always 'drive#label').
              Optional; default: 'drive#label'.
            - modifiedLabels[].revisionId (str): The revision ID of the label. Defaults to
              '' (empty string). Optional; default: ''.
            - modifiedLabels[].fields (dict | None): A map of the fields on the label, keyed
              by field ID. Defaults to {} (matches DriveLabel.fields). Optional; nullable;
              default: {}.

    Raises:
        TypeError:
            Raised if 'fileId' is not a string. Raised if 'labelModifications' is not a
            list.
        ValidationError:
            Raised if 'fileId' is an empty string or consists only of whitespace. Raised if
            'labelModifications' is empty. Raised if 'labelId' in a modification is empty.
            Raised if 'fieldId' in a field modification is empty. Raised if both
            'removeLabel' and 'fieldModifications' are specified for the same label. Raised
            if setDateValues contains a value that is not in YYYY-MM-DD format. Raised if
            setIntegerValues contains a non-numeric value or a value outside the signed
            int64 range. Raised if setUserValues contains a value that is not a valid email
            address.
        ResourceNotFoundError:
            Raised if the default 'me' user is missing or not configured. Raised if the file
            with the specified 'fileId' does not exist.
        InvalidRequestError:
            Raised if the request contains conflicting parameters. Raised if multiple value
            setters are specified for the same field modification.
        PermissionDeniedError:
            Raised if the caller lacks writer access or higher on the file.
    """
    userId = get_current_user_id()

    if userId not in DB.get("users", {}):
        raise ResourceNotFoundError("Internal error: User 'me' not found or not configured.")

    user_data = DB["users"][userId]
    user_files = user_data.get("files", {})
    if fileId not in user_files:
        raise ResourceNotFoundError(f"File with ID '{fileId}' not found.")

    file_data = user_files[fileId]
    user_email = read_user_email(userId)
    user_role = _get_user_role_on_file(user_email, file_data, user_data)
    label_modify_role_priority = {
        "reader": 1,
        "viewer": 1,
        "commenter": 2,
        "writer": 3,
        "editor": 3,
        "contributor": 3,
        "fileOrganizer": 4,
        "content manager": 4,
        "organizer": 5,
        "manager": 5,
        "owner": 6,
    }
    role_priority = label_modify_role_priority.get(user_role, -1) if user_role else -1
    if role_priority < 3:
        raise PermissionDeniedError(
            f"User does not have permission to modify labels on file '{fileId}'. "
            "Writer access or higher is required."
        )

    # Initialize labels array if not present
    if "labels" not in file_data or file_data["labels"] is None:
        file_data["labels"] = []

    # Normalize any legacy Label-format objects ({id, fileId, name, color})
    # to DriveLabel format ({id, kind, revisionId, fields}) so that
    # subsequent mutations don't create hybrid objects.
    labels_by_id = {}
    for label in file_data["labels"]:
        resolved = _resolve_file_label_entry(label, userId)
        labels_by_id[resolved.get("id", "")] = resolved

    modified_labels = []

    # Process each modification atomically
    for modification in labelModifications:
        label_id = modification.get("labelId", "")
        remove_label = modification.get("removeLabel", False)
        field_modifications = modification.get("fieldModifications", [])

        if remove_label:
            labels_by_id.pop(label_id, None)
            # Don't add to modifiedLabels for removals
        else:
            # Add or update the label
            label_existed = label_id in labels_by_id
            if label_existed:
                label = labels_by_id[label_id]
            else:
                label = {
                    "id": label_id,
                    "kind": "drive#label",
                    "revisionId": str(uuid.uuid4()),  # Generate new revision ID
                    "fields": {},
                }
                labels_by_id[label_id] = label

            fields_changed = False

            # Apply field modifications
            if field_modifications:
                if "fields" not in label or label["fields"] is None:
                    label["fields"] = {}

                for field_mod in field_modifications:
                    field_id = field_mod.get("fieldId", "")
                    unset_values = field_mod.get("unsetValues", False)

                    if unset_values:
                        # Remove the field entirely
                        if field_id in label["fields"]:
                            del label["fields"][field_id]
                            fields_changed = True
                    else:
                        # Determine the value type and set the field
                        field_data = {
                            "kind": "drive#labelField",
                            "id": field_id,
                        }

                        if field_mod.get("setDateValues") is not None:
                            field_data["valueType"] = "dateString"
                            field_data["dateString"] = field_mod["setDateValues"]
                        elif field_mod.get("setIntegerValues") is not None:
                            field_data["valueType"] = "integer"
                            field_data["integer"] = field_mod["setIntegerValues"]
                        elif field_mod.get("setSelectionValues") is not None:
                            field_data["valueType"] = "selection"
                            field_data["selection"] = field_mod["setSelectionValues"]
                        elif field_mod.get("setTextValues") is not None:
                            field_data["valueType"] = "text"
                            field_data["text"] = field_mod["setTextValues"]
                        elif field_mod.get("setUserValues") is not None:
                            field_data["valueType"] = "user"
                            # Convert email addresses to user objects
                            user_objects = []
                            for email in field_mod["setUserValues"]:
                                user_objects.append({
                                    "emailAddress": email,
                                    "displayName": None,
                                    "photoLink": None,
                                    "me": email.lower()
                                    == read_email_from_user_record(DB["users"].get(userId, {})),
                                    "permissionId": None,
                                })
                            field_data["user"] = user_objects
                        else:
                            # No value setter provided, skip this field
                            continue

                        label["fields"][field_id] = field_data
                        fields_changed = True

                if fields_changed:
                    label["revisionId"] = str(uuid.uuid4())

            if not label_existed or fields_changed:
                modified_labels.append(label)

    # Convert labels_by_id back to list and update file
    file_data["labels"] = builtins.list(labels_by_id.values())

    return {
        "kind": "drive#modifyLabelsResponse",
        "modifiedLabels": modified_labels if modified_labels else None,
    }


